{"code": "import json
import urllib.request
import urllib.parse

def search_wikipedia(query):
    """Search Wikipedia API for a topic"""
    url = f"https://en.wikipedia.org/w/api.php?action=opensearch&search={urllib.parse.quote(query)}&limit=5&format=json"
    try:
        req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
        with urllib.request.urlopen(req, timeout=10) as resp:
            return json.loads(resp.read().decode())
    except Exception as e:
        return [query, [], [], f"Error: {e}"]

# Search for top companies in each sector
sectors = {
    "AI/ML": ["largest artificial intelligence companies 2025", "OpenAI Microsoft Nvidia Alphabet"],
    "Semiconductors": ["largest semiconductor companies 2025 market cap", "NVIDIA TSMC AMD Intel Broadcom"],
    "Cloud": ["largest cloud computing companies 2025 market share", "Amazon Microsoft Google Alibaba"],
    "E-commerce": ["largest e-commerce companies 2025 market cap", "Amazon Alibaba Shopify Mercado Libre"],
    "Cybersecurity": ["largest cybersecurity companies 2025 market cap", "Palo Alto Networks CrowdStrike Fortinet"]
}

for sector, queries in sectors.items():
    print(f"\n=== {sector} ===")
    for q in queries[:2]:
        result = search_wikipedia(q)
        print(f"  Query: {q}")
        print(f"  Results: {result[1][:5] if result[1] else 'None'}")"}
